## Research Plan
{
  "topic": "Develop a Flappy Bird‑style 2D game where the player controls a man character that overcomes obstacles, covering game mechanics, physics, sprite animation, input handling, asset sourcing, cross‑platform deployment, and common pitfalls.",
  "keywords": [
    {
      "query": "flappy bird clone tutorial unity 2d",
      "reason": "Find step‑by‑step Unity implementations to understand core mechanics (gravity, pipe spawning, scoring) that can be adapted for a man character."
    },
    {
      "query": "flappy bird clone tutorial godot 4 2d",
      "reason": "Gather Godot‑specific guidance for developers preferring an open‑source engine; includes GDScript examples of physics and collision."
    },
    {
      "query": "phaser 3 flappy bird example source code",
      "reason": "Locate JavaScript/HTML5 examples for web deployment, covering canvas rendering, input, and asset preloading."
    },
    {
      "query": "2d character sprite sheet free man running jump",
      "reason": "Identify royalty‑free sprite sheets (CC0/BY) for the man protagonist, ensuring correct frame layout for flap/jump animation."
    },
    {
      "query": "obstacle sprite sheet flappy bird pipe alternative assets",
      "reason": "Find alternative obstacle graphics (e.g., floating platforms, swinging hammers) that match the man‑overcoming‑obstacles theme."
    },
    {
      "query": "unity 2d physics gravity settings best practices",
      "reason": "Understand how to tune gravity and Rigidbody2D parameters for a smooth, responsive “flap” motion."
    },
    {
      "query": "procedural level generation flappy bird obstacles algorithm",
      "reason": "Research algorithms for randomizing gap size, obstacle spacing, and difficulty scaling."
    },
    {
      "query": "mobile input handling flappy bird tap swipe Unity",
      "reason": "Collect best practices for touch input on iOS/Android, including handling taps vs. swipes and low‑latency response."
    },
    {
      "query": "flappy bird game over collision detection edge cases",
      "reason": "Identify common pitfalls (e.g., tunneling, multiple collisions) and robust ways to detect game‑over conditions."
    },
    {
      "query": "open game art flappy bird assets license cc0",
      "reason": "Locate an asset pack that includes background, ground, and UI elements with a permissive license for immediate use."
    }
  ],
  "scrapeTargets": [
    {
      "url": "https://learn.unity.com/tutorial/2d-game-kit",
      "reason": "Extract Unity 2D project setup steps, Rigidbody2D configuration, and prefab handling relevant to a Flappy‑style game."
    },
    {
      "url": "https://docs.godotengine.org/en/stable/tutorials/2d/2d_movement.html",
      "reason": "Gather official Godot documentation on 2D physics, KinematicBody2D movement, and input mapping."
    },
    {
      "url": "https://phaser.io/tutorials/making-your-first-phaser-3-game",
      "reason": "Pull code snippets for asset loading, game loop, and input handling in Phaser 3 to adapt for a web version."
    },
    {
      "url": "https://opengameart.org/art-search-advanced?keys=flappy+bird&field_art_type_tid=All&field_tags_tid=All&field_license_tid=CC0",
      "reason": "Scrape a list of CC0‑licensed sprites and background tiles that can replace the bird with a man and provide matching obstacles."
    },
    {
      "url": "https://sketchfab.com/search?q=man+character+low+poly&downloadable=1&sort_by=-likeCount",
      "reason": "Identify downloadable low‑poly 3D models (if the project later expands to 3D) and capture licensing info."
    }
  ]
}
